/**
 * Storage Mart TMS - Application Utilities
 * Placeholder file for common application functionality
 */

(function() {
    'use strict';

    // Application namespace
    window.StorageMart = window.StorageMart || {};

    // Initialize tooltips and popovers if Bootstrap is loaded
    if (typeof bootstrap !== 'undefined') {
        document.addEventListener('DOMContentLoaded', function() {
            // Initialize tooltips
            var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
            tooltipTriggerList.map(function (tooltipTriggerEl) {
                return new bootstrap.Tooltip(tooltipTriggerEl);
            });

            // Initialize popovers
            var popoverTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="popover"]'));
            popoverTriggerList.map(function (popoverTriggerEl) {
                return new bootstrap.Popover(popoverTriggerEl);
            });
        });
    }

    // Common utility functions
    StorageMart.alert = function(message, type) {
        type = type || 'info';
        var alertClass = 'alert-' + type;
        console.log('[' + type.toUpperCase() + '] ' + message);
    };

    StorageMart.showLoading = function() {
        if (document.body) {
            var loader = document.createElement('div');
            loader.id = 'storage-mart-loader';
            loader.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;z-index:9999;';
            loader.innerHTML = '<div style="color:white;font-size:18px;">Loading...</div>';
            document.body.appendChild(loader);
        }
    };

    StorageMart.hideLoading = function() {
        var loader = document.getElementById('storage-mart-loader');
        if (loader) {
            loader.remove();
        }
    };

    // Page-specific initialization
    document.addEventListener('DOMContentLoaded', function() {
        // Initialize active menu states
        var currentPath = window.location.pathname;
        var navLinks = document.querySelectorAll('a[href]');
        navLinks.forEach(function(link) {
            if (link.getAttribute('href') === currentPath) {
                link.classList.add('active');
            }
        });
    });

})();
